/**
 * teacherAI.js
 * ------------------------------------------------------------
 * Analytics + Activity Review for the Teacher/Admin dashboard.
 * Uses Chart.js (loaded globally via CDN in teacher.html, client-side
 * rendering only) for charts, and firebase.js for the Firestore-backed
 * waste-identification activity log.
 *
 * "AI Insights" are generated by a local, rule-based summarizer — plain
 * JavaScript logic over the aggregated Firestore stats, no external AI
 * API of any kind, so this works entirely on the free Spark plan.
 * ------------------------------------------------------------
 */
import { getAllWasteLogs } from "../firebase.js";

const LEVEL_MAP = {
  1: "beginner", 2: "beginner", 3: "beginner", 4: "beginner",
  5: "intermediate", 6: "intermediate", 7: "intermediate", 8: "intermediate", 9: "intermediate",
  10: "advanced", 11: "advanced", 12: "advanced", 13: "advanced",
  14: "expert", 15: "expert", 16: "expert", 17: "expert",
};

function levelOf(scoreField) {
  const n = parseInt(scoreField, 10);
  return LEVEL_MAP[n] || "beginner";
}

let charts = {};
let lastScoresCache = [];

function renderAnalytics(scores) {
  lastScoresCache = scores || [];
  renderLevelChart(lastScoresCache);
  renderLangChart(lastScoresCache);
  renderAtRisk(lastScoresCache);
}

function renderLevelChart(scores) {
  const buckets = { beginner: [], intermediate: [], advanced: [], expert: [] };
  scores.forEach((s) => {
    const lvl = levelOf(s.level);
    if (!s.total) return;
    buckets[lvl].push((s.score / s.total) * 100);
  });
  const labels = Object.keys(buckets);
  const data = labels.map((l) => (buckets[l].length ? Math.round(buckets[l].reduce((a, b) => a + b, 0) / buckets[l].length) : 0));

  const ctx = document.getElementById("chart-level-avg");
  if (!ctx || typeof Chart === "undefined") return;
  if (charts.level) charts.level.destroy();
  charts.level = new Chart(ctx, {
    type: "bar",
    data: {
      labels,
      datasets: [{ label: "Avg Score %", data, backgroundColor: ["#39FF14", "#FFD700", "#2ECC71", "#BF5FFF"] }],
    },
    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } }, plugins: { legend: { display: false } } },
  });
}

function renderLangChart(scores) {
  const counts = { en: 0, ta: 0 };
  scores.forEach((s) => { counts[s.language === "ta" ? "ta" : "en"]++; });
  const ctx = document.getElementById("chart-lang-split");
  if (!ctx || typeof Chart === "undefined") return;
  if (charts.lang) charts.lang.destroy();
  charts.lang = new Chart(ctx, {
    type: "doughnut",
    data: {
      labels: ["English", "Tamil"],
      datasets: [{ data: [counts.en, counts.ta], backgroundColor: ["#4DD0E1", "#BF5FFF"] }],
    },
    options: { responsive: true },
  });
}

function renderAtRisk(scores) {
  const byStudent = {};
  scores.forEach((s) => {
    const key = s.name || "Unknown";
    if (!byStudent[key]) byStudent[key] = { earned: 0, total: 0, attempts: 0 };
    byStudent[key].earned += s.score || 0;
    byStudent[key].total += s.total || 0;
    byStudent[key].attempts++;
  });
  const rows = Object.entries(byStudent)
    .map(([name, d]) => ({ name, pct: d.total ? Math.round((d.earned / d.total) * 100) : 0, attempts: d.attempts }))
    .filter((r) => r.pct < 60)
    .sort((a, b) => a.pct - b.pct)
    .slice(0, 10);

  const el = document.getElementById("at-risk-list");
  if (!el) return;
  if (!rows.length) {
    el.innerHTML = `<div style="color:var(--text-muted,#888);font-size:.85rem;">🎉 No students currently below 60% average — nice work!</div>`;
    return;
  }
  el.innerHTML = rows
    .map((r) => `<div class="at-risk-row"><span>${r.name} <span style="opacity:.6">(${r.attempts} attempts)</span></span><span class="pct">${r.pct}%</span></div>`)
    .join("");
}

/**
 * Builds a concise, teacher-facing analytics summary from aggregated
 * Firestore stats using plain rule-based logic — no external AI API.
 */
function buildLocalInsights(stats) {
  const { totalAttempts, totalStudents, perLevelAverageScorePct, strugglingStudents, languageSplit } = stats;

  if (!totalAttempts) {
    return "No quiz attempts yet. Insights will appear here once students start completing levels.";
  }

  const lines = [];

  // Overall class health
  const levelPcts = Object.values(perLevelAverageScorePct).filter((v) => v !== null);
  const overallAvg = levelPcts.length ? Math.round(levelPcts.reduce((a, b) => a + b, 0) / levelPcts.length) : 0;
  const healthLabel = overallAvg >= 80 ? "excellent 🌟" : overallAvg >= 60 ? "good 👍" : "needs attention ⚠️";
  lines.push(`**Overall class health:** ${healthLabel} — average score across active levels is ${overallAvg}% from ${totalAttempts} attempts by ${totalStudents} student(s).`);

  // Struggling levels
  const sortedLevels = Object.entries(perLevelAverageScorePct)
    .filter(([, v]) => v !== null)
    .sort((a, b) => a[1] - b[1]);
  const weakLevels = sortedLevels.filter(([, v]) => v < 60).slice(0, 3);
  if (weakLevels.length) {
    lines.push(`**Struggling difficulty tiers:** ${weakLevels.map(([lvl, v]) => `${lvl} (${v}%)`).join(", ")}.`);
  } else {
    lines.push("**Struggling difficulty tiers:** none — all tiers are averaging 60% or above.");
  }

  // Students needing attention
  if (strugglingStudents.length) {
    lines.push(`**Students who may need attention:** ${strugglingStudents.slice(0, 6).join(", ")}${strugglingStudents.length > 6 ? `, +${strugglingStudents.length - 6} more` : ""}.`);
  } else {
    lines.push("**Students who may need attention:** none currently below 60% average.");
  }

  // Suggestions (rule-based)
  const suggestions = [];
  if (weakLevels.length) suggestions.push(`Revisit the syllabus notes for the ${weakLevels[0][0]} tier as a class before the next quiz attempt.`);
  if (strugglingStudents.length) suggestions.push("Pair struggling students with a peer who scored well on the same level for quick peer review.");
  if (languageSplit.ta > 0) suggestions.push("Some students are using the Tamil interface — check the Tamil-language tab for a language-specific breakdown.");
  if (!suggestions.length) suggestions.push("Class is performing well — consider introducing the Daily Eco Challenge as a bonus activity.");
  lines.push(`**Suggestions:** ${suggestions.join(" ")}`);

  return lines.join("\n\n");
}

function refreshInsights() {
  const body = document.getElementById("ai-insights-body");
  if (!body) return;
  body.textContent = "Analyzing class performance…";

  const buckets = { beginner: [], intermediate: [], advanced: [], expert: [] };
  lastScoresCache.forEach((s) => {
    if (!s.total) return;
    buckets[levelOf(s.level)].push((s.score / s.total) * 100);
  });
  const perLevelAvg = {};
  Object.entries(buckets).forEach(([lvl, arr]) => {
    perLevelAvg[lvl] = arr.length ? Math.round(arr.reduce((a, b) => a + b, 0) / arr.length) : null;
  });

  const byStudent = {};
  lastScoresCache.forEach((s) => {
    const key = s.name || "Unknown";
    if (!byStudent[key]) byStudent[key] = { earned: 0, total: 0 };
    byStudent[key].earned += s.score || 0;
    byStudent[key].total += s.total || 0;
  });
  const strugglingStudents = Object.entries(byStudent)
    .map(([name, d]) => ({ name, pct: d.total ? Math.round((d.earned / d.total) * 100) : 0 }))
    .filter((r) => r.pct < 60)
    .sort((a, b) => a.pct - b.pct)
    .slice(0, 8)
    .map((r) => r.name);

  const stats = {
    totalAttempts: lastScoresCache.length,
    totalStudents: Object.keys(byStudent).length,
    perLevelAverageScorePct: perLevelAvg,
    strugglingStudents,
    languageSplit: {
      en: lastScoresCache.filter((s) => s.language !== "ta").length,
      ta: lastScoresCache.filter((s) => s.language === "ta").length,
    },
  };

  // Small delay purely for perceived responsiveness; this is a synchronous,
  // local computation with no network round-trip.
  setTimeout(() => {
    body.innerHTML = buildLocalInsights(stats).replace(/\n\n/g, "<br><br>").replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
  }, 200);
}

async function renderWasteLog() {
  const grid = document.getElementById("activity-review-grid");
  if (!grid) return;
  grid.textContent = "Loading waste identification activity...";
  try {
    const logs = await getAllWasteLogs();
    if (!logs.length) {
      grid.innerHTML = `<div style="color:var(--text-muted,#888);">No Eco Waste Identification activity yet.</div>`;
      return;
    }
    grid.innerHTML = logs
      .map((l) => `
        <div class="activity-review-card waste-log-card">
          <div class="activity-review-body">
            <div><strong>${l.studentName || "unknown"}</strong></div>
            <div class="activity-review-verdict ${l.biodegradable ? "ok" : "bad"}">
              ${l.itemName || "Item"} — ${l.wasteType || ""} ${l.biodegradable ? "🌿 Biodegradable" : "🚫 Non-biodegradable"}
            </div>
            <div style="opacity:.6;font-size:.72rem;">${l.timestamp ? new Date(l.timestamp).toLocaleString() : ""}</div>
          </div>
        </div>`)
      .join("");
  } catch (e) {
    console.error(e);
    grid.innerHTML = `<div style="color:#ff5c8a;">Failed to load waste identification activity.</div>`;
  }
}

window.TeacherAI = { renderAnalytics, refreshInsights, renderWasteLog };
